dslRule:
java.lang.StringBuffer $var = new java.lang.StringBuffer($args$);
=> java.lang.StringBuilder $var = new java.lang.StringBuilder($args$);
;;

beforeExample:
public class Example {
    void method() {
        java.lang.StringBuffer sb = new java.lang.StringBuffer();
        sb.append("Hello");
        String result = sb.toString();
    }
    void anotherMethod(int capacity) {
        java.lang.StringBuffer anotherSb = new java.lang.StringBuffer(capacity);
        anotherSb.reverse();
    }
}

afterExample:
public class Example {
    void method() {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        sb.append("Hello");
        String result = sb.toString();
    }
    void anotherMethod(int capacity) {
        java.lang.StringBuilder anotherSb = new java.lang.StringBuilder(capacity);
        anotherSb.reverse();
    }
}

negativeExample:
public class NegativeExample {
    // This should not match because it's a field, not a local variable declaration.
    // Replacing fields requires deeper thread-safety analysis not available to the DSL.
    private java.lang.StringBuffer fieldBuffer = new java.lang.StringBuffer();

    void method() {
        java.lang.String s = "test";
        // This should not match because it's an assignment, not a declaration.
        fieldBuffer = new java.lang.StringBuffer(s);

        // This should not match because the variable type is not explicitly StringBuffer.
        // The rule targets explicit 'java.lang.StringBuffer $var = ...'
        var inferredSb = new java.lang.StringBuffer();
    }
}
